    /// <summary>
    /// Performs a blocking wait on @id.
    /// @id should have been created with gst_clock_new_single_shot_id()
    /// or gst_clock_new_periodic_id() and should not have been unscheduled
    /// with a call to gst_clock_id_unschedule().
    /// </summary>
    /// <remarks>
    /// <para>
    /// If the @jitter argument is not %NULL and this function returns #GST_CLOCK_OK
    /// or #GST_CLOCK_EARLY, it will contain the difference
    /// against the clock and the time of @id when this method was
    /// called.
    /// Positive values indicate how late @id was relative to the clock
    /// (in which case this function will return #GST_CLOCK_EARLY).
    /// Negative values indicate how much time was spent waiting on the clock
    /// before this function returned.
    /// </para>
    /// </remarks>
    /// <param name="id">The #GstClockID to wait on</param>
    /// <param name="jitter">
    /// a pointer that will contain the jitter,
    ///     can be %NULL.
    /// </param>
    /// <returns>
    /// the result of the blocking wait. #GST_CLOCK_EARLY will be returned
    /// if the current clock time is past the time of @id, #GST_CLOCK_OK if
    /// @id was scheduled in time. #GST_CLOCK_UNSCHEDULED if @id was
    /// unscheduled with gst_clock_id_unschedule().
    /// </returns>
    public static Gst.ClockReturn IdWait(nint id, out long jitter)
    {
        long jitterNative = default;
        int nativeResult = GstClockIdWait(id, &jitterNative);
        jitter = jitterNative;
        return (Gst.ClockReturn)nativeResult;
    }

